SELECT o.id, o.shop_id, o.user_id, o.order_no, o.is_deleted, o.pay_amount, o.pay_type, o.order_status, o.remark, o.consignee, o.phone, o.region, o.detail_address, o.shipping_type, o.courier, o.tracking_number, o.sign_status, o.created_at, o.pay_at, o.ship_at, o.confirm_at, o.finish_at, o.updated_at FROM orders o WHERE o.shop_id = #{shopId} AND o.is_deleted = 0
AND o.order_status = #{status}
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR o.consignee LIKE CONCAT('%', #{keyword}, '%') OR o.phone LIKE CONCAT('%', #{keyword}, '%') OR EXISTS (SELECT 1 FROM order_items oi WHERE oi.order_id = o.id AND oi.product_name LIKE CONCAT('%', #{keyword}, '%')))
AND o.${dateField} >= #{startDate}
AND o.${dateField} <= #{endDate}
ORDER BY o.created_at DESC, o.id DESC LIMIT #{offset}, #{pageSize}

